apps.compose:
services:
  qbittorrent:
    image: lscr.io/linuxserver/qbittorrent:5.3.0_v2.1.2-ls486@sha256:05c1454f9a32967affc1f34f67f8cc0cc57dd805dca45489fe797095a6286556
    restart: unless-stopped
    user: ${PUID}:${PGID}
    environment:
      TZ: ${TZ}
      WEBUI_PORT: ${PORT_WEB}
      TORRENTING_PORT: ${PORT_PEER}
    ports:
      - ${PORT_WEB}:${PORT_WEB}
      - ${PORT_PEER}:${PORT_PEER}
      - ${PORT_PEER}:${PORT_PEER}/udp
    volumes:
      - ${APP_DATA}/config:/config
      - ${SHARE_DOWNLOADS}:/downloads

services:
  transmission:
    image: lscr.io/linuxserver/transmission:4.1.4-r0-ls368@sha256:fb8fe625941cf15eb69aba4e5c0a678e035ddb11605fd85af4516a4e641f2687
    restart: unless-stopped
    user: ${PUID}:${PGID}
    environment:
      TZ: ${TZ}
      USER: ${WEB_USER}
      PASS: ${WEB_PASSWORD}
      PEERPORT: ${PORT_PEER}
    ports:
      - ${PORT_WEB}:9091
      - ${PORT_PEER}:${PORT_PEER}
      - ${PORT_PEER}:${PORT_PEER}/udp
    volumes:
      - ${APP_DATA}/config:/config
      - ${SHARE_DOWNLOADS}:/downloads
